"""RGA variant backing :class:`~crdt_sync.rga_session.RGASession`.

This subclass keeps the bare :class:`~crdt_sync.rga.RGA` insertion history and
tombstone semantics but adds the two pieces of causal metadata that safe
sequence compaction needs:

* ``_deletes`` maps every tombstoned node to the vector-clock components
  observed by the replica that performed the delete. The components travel
  with snapshots and merge component-wise, so a delete's whole causal
  ancestry is knowable on every replica without changing how deletes are
  applied (a node is deleted as soon as *anyone* observed it deleted).
* ``_retired`` is the retirement summary: a compacted node id maps to the
  delete components recorded when it was reclaimed. Retired records merge
  by component-wise maximum and make every node listed in them permanently
  absent, so a late pre-compaction snapshot, a duplicated packet or an
  out-of-order packet can never resurrect a reclaimed node.

Tombstones whose delete ancestry is unknown (the historical four-field RGA
snapshot shape) are kept with no delete record and are therefore never
eligible for compaction; their deletion time is never guessed.
"""

from __future__ import annotations

from .rga import ROOT, RGA, NodeId

Components = dict[str, int]


def _parse_components(raw: object) -> Components:
    """Parse one JSON-shape vector-clock component mapping."""
    if not isinstance(raw, dict):
        raise ValueError("delete causal context must be a dict")
    components: Components = {}
    for replica_id, value in raw.items():
        if not isinstance(replica_id, str) or replica_id == "":
            raise ValueError(
                "delete causal context keys must be non-empty strings"
            )
        if not isinstance(value, int) or isinstance(value, bool) or value < 0:
            raise ValueError(
                "delete causal context values must be non-negative integers"
            )
        components[replica_id] = value
    return components


def _merge_components(left: Components, right: Components) -> Components:
    """Component-wise maximum of two causal-context mappings."""
    merged = dict(left)
    for replica_id, value in right.items():
        if value > merged.get(replica_id, 0):
            merged[replica_id] = value
    return merged


class SessionRGA(RGA):
    """An :class:`RGA` carrying per-delete causal context and retirement data."""

    def __init__(self, replica_id: str) -> None:
        super().__init__(replica_id)
        # Tombstoned node id -> components observed by its deleter. A
        # tombstone missing here has unknown delete ancestry (legacy shape)
        # and can never be compacted.
        self._deletes: dict[NodeId, Components] = {}
        # Retired (compacted away) node id -> delete components certified at
        # retirement. Only ever grows; merge takes the component-wise max.
        self._retired: dict[NodeId, Components] = {}

    # -- visibility ---------------------------------------------------------

    def _known_node(self, node_id: NodeId) -> bool:
        return node_id in self._nodes or node_id in self._retired

    def _is_deleted(self, node_id: NodeId) -> bool:
        return node_id in self._tombstones or node_id in self._retired

    def _visible_nodes(self) -> list[NodeId]:
        """Like RGA's weave, but skipping retired nodes and branches.

        Retired nodes no longer have an insert record and can never become
        visible again. A still-retained node that hangs off a retired
        predecessor cannot occur in a locally compacted history (compaction
        removes leaves first), but may briefly exist while a stale
        pre-compaction packet is being filtered on merge; such dangling
        branches are simply not walked.
        """
        children: dict[NodeId | None, list[NodeId]] = {}
        for node_id, (_value, predecessor) in self._nodes.items():
            children.setdefault(predecessor, []).append(node_id)
        for siblings in children.values():
            siblings.sort(reverse=True)

        ordered: list[NodeId] = []
        stack: list[NodeId] = list(reversed(children.get(ROOT, ())))
        while stack:
            node_id = stack.pop()
            if node_id in self._tombstones:
                continue
            ordered.append(node_id)
            stack.extend(reversed(children.get(node_id, ())))
        return ordered

    # -- edits --------------------------------------------------------------

    def record_delete_context(
        self, node_id: NodeId, components: Components
    ) -> None:
        """Attach the deleter's observed clock components to a tombstone."""
        existing = self._deletes.get(node_id)
        if existing is None:
            self._deletes[node_id] = dict(components)
        else:
            merged = _merge_components(existing, components)
            self._deletes[node_id] = merged

    # -- merge --------------------------------------------------------------

    def merge(self, other: "RGA") -> "SessionRGA":
        """Union ``other``'s history, tombstones and compaction metadata.

        Insertion records and tombstones follow the ordinary RGA union
        rules. Retirement summaries are joined by component-wise maximum;
        any node the joined summary certifies as retired is removed from
        this side's explicit records (so a late or duplicated
        pre-compaction snapshot cannot resurrect it), and incoming records
        a summary already certifies are ignored. Raises ``TypeError`` for a
        non-RGA argument and ``ValueError`` — before touching any state —
        when the same retained node id carries a different value or
        predecessor.
        """
        if not isinstance(other, RGA):
            raise TypeError("can only merge with another RGA")

        other_deletes: dict[NodeId, Components] = getattr(
            other, "_deletes", {}
        )
        other_retired: dict[NodeId, Components] = getattr(
            other, "_retired", {}
        )

        # Join the retirement summaries up front; everything below filters on
        # the joined view, mirroring how ORSet joins bounds first.
        retired: dict[NodeId, Components] = dict(self._retired)
        for node_id, components in other_retired.items():
            retired[node_id] = _merge_components(
                retired.get(node_id, {}), components
            )

        def retired_here(node_id: NodeId) -> bool:
            return node_id in retired

        # Validate shared retained records before mutating anything so a
        # conflict leaves the whole merge atomic. Records a summary already
        # certifies as retired are consumed history and take no part.
        for node_id, (value, predecessor) in other._nodes.items():
            if retired_here(node_id):
                continue
            local = self._nodes.get(node_id)
            if local is not None and local != (value, predecessor):
                raise ValueError(
                    "the same node id is bound to a different value or "
                    "predecessor"
                )

        # A retained node may not be reintroduced on top of a predecessor the
        # joined summary has retired, since the retired predecessor's insert
        # record is gone for good.
        for node_id, (_value, predecessor) in other._nodes.items():
            if (
                not retired_here(node_id)
                and predecessor is not None
                and retired_here(predecessor)
                and predecessor not in self._nodes
                and predecessor not in other._nodes
            ):
                raise ValueError(
                    "node record hangs off a retired predecessor"
                )

        self._retired = retired

        # A higher summary learned from ``other`` may retire records this
        # replica still held explicitly; consume them exactly like a local
        # compaction would, so joins converge on one canonical state.
        for node_id in list(self._nodes):
            if node_id in retired:
                del self._nodes[node_id]
        self._tombstones = {
            node_id for node_id in self._tombstones if node_id not in retired
        }
        self._deletes = {
            node_id: context
            for node_id, context in self._deletes.items()
            if node_id not in retired or node_id in self._tombstones
        }

        # Union the surviving records above the joined retirement summary.
        for node_id, record in other._nodes.items():
            if node_id not in retired and node_id not in self._nodes:
                self._nodes[node_id] = record
        for node_id in other._tombstones:
            if node_id not in retired and node_id in self._nodes:
                self._tombstones.add(node_id)

        # Join delete causal context for every tombstone still retained.
        for node_id, components in other_deletes.items():
            if node_id in self._tombstones:
                self.record_delete_context(node_id, components)

        if other._counter > self._counter:
            self._counter = other._counter
        return self

    # -- snapshots ----------------------------------------------------------

    def session_snapshot(self) -> dict[str, object]:
        """Return the five-field session RGA snapshot shape.

        Carries the ordinary RGA fields plus the per-node delete causal
        context and the retirement summary; both extra mappings are omitted
        while empty, so a session that never deleted anything serializes
        like the classic shape.
        """
        snapshot = self.snapshot()
        if self._deletes:
            snapshot["deletes"] = self._encode_contexts(self._deletes)
        if self._retired:
            snapshot["retired"] = self._encode_contexts(self._retired)
        return snapshot

    @staticmethod
    def _encode_contexts(mapping: dict[NodeId, Components]) -> dict[str, object]:
        encoded: dict[str, object] = {}
        for sequence, origin in sorted(mapping):
            components = mapping[(sequence, origin)]
            encoded[f"{sequence}:{origin}"] = {
                replica_id: components[replica_id]
                for replica_id in sorted(components)
            }
        return encoded

    @classmethod
    def session_from_snapshot(
        cls, snapshot: object, require_session_fields: bool = False
    ) -> "SessionRGA":
        """Restore from a classic four-field or session five/six-field shape.

        ``deletes``/``retired`` are accepted only together as the session
        extension when ``require_session_fields`` is false; the classic RGA
        shape restores with empty causal metadata, which leaves every
        tombstone ineligible for compaction.
        """
        if not isinstance(snapshot, dict):
            raise TypeError("snapshot must be a dict")

        base_keys = {"replica_id", "counter", "nodes", "tombstones"}
        extension_keys = {"deletes", "retired"}
        keys = set(snapshot.keys())
        if keys == base_keys:
            has_extension = False
        elif keys <= base_keys | extension_keys and extension_keys <= keys:
            has_extension = True
        else:
            raise ValueError(
                "snapshot must contain 'replica_id', 'counter', 'nodes' and "
                "'tombstones', and the session snapshot must also carry "
                "'deletes' and 'retired'"
            )
        if require_session_fields and not has_extension:
            raise ValueError(
                "session rga snapshot must carry 'deletes' and 'retired'"
            )

        # Parse the ordinary RGA fields through the base validator first.
        base = RGA.from_snapshot(
            {key: snapshot[key] for key in base_keys}
        )

        deletes: dict[NodeId, Components] = {}
        retired: dict[NodeId, Components] = {}
        if has_extension:
            raw_deletes = snapshot["deletes"]
            raw_retired = snapshot["retired"]
            if not isinstance(raw_deletes, dict):
                raise ValueError("deletes must be a dict")
            if not isinstance(raw_retired, dict):
                raise ValueError("retired must be a dict")
            for raw_id, raw_context in raw_deletes.items():
                node_id = _parse_context_key(raw_id)
                deletes[node_id] = _parse_components(raw_context)
            for raw_id, raw_context in raw_retired.items():
                node_id = _parse_context_key(raw_id)
                if node_id in retired:
                    raise ValueError("duplicate retired entry")
                retired[node_id] = _parse_components(raw_context)

        nodes = base._nodes
        tombstones = base._tombstones

        # Structural checks on the causal metadata.
        for node_id in deletes:
            if node_id not in tombstones:
                raise ValueError(
                    "delete context must belong to a tombstoned node"
                )
            if node_id in retired:
                raise ValueError("a retired node must keep no delete record")
        for node_id, components in retired.items():
            if node_id in tombstones:
                raise ValueError("a retired node must keep no tombstone")
            if node_id in nodes:
                raise ValueError("a retired node must keep no insert record")
            if not components:
                raise ValueError(
                    "retirement summary must carry the delete causal context"
                )
        if has_extension and set(deletes) | set(retired) != set(
            deletes
        ) | set(retired):
            raise ValueError("a node cannot be both deleted and retired")

        restored = cls(base.replica_id)
        restored._counter = base._counter
        restored._nodes = nodes
        restored._tombstones = tombstones
        restored._deletes = deletes
        restored._retired = retired
        return restored


def _parse_context_key(raw_key: object) -> NodeId:
    """Parse a ``"<sequence>:<origin>"`` retirement/deletes mapping key."""
    if not isinstance(raw_key, str):
        raise ValueError("causal node keys must be strings")
    marker = raw_key.find(":")
    if marker <= 0 or marker == len(raw_key) - 1:
        raise ValueError("causal node keys must be '<sequence>:<origin>'")
    raw_sequence, origin = raw_key[:marker], raw_key[marker + 1:]
    if not raw_sequence.isdigit():
        raise ValueError("causal node key sequence must be a positive integer")
    sequence = int(raw_sequence)
    if sequence < 1:
        raise ValueError("causal node key sequence must be a positive integer")
    if not isinstance(origin, str) or origin == "":
        raise ValueError("causal node key origin must be a non-empty string")
    return sequence, origin

