        # on the joined view, mirroring how ORSet joins bounds first.
        retired: dict[NodeId, tuple[NodeId | None, Components]] = {}
        for node_id, (predecessor, components) in self._retired.items():
            retired[node_id] = (predecessor, dict(components))
        for node_id, (predecessor, components) in other_retired.items():
