        # agree on the anchor recorded in the retirement summary.
        for node_id, (predecessor, _components) in retired.items():
            if node_id in other_retired and node_id in self._nodes:
                if self._nodes[node_id][1] != predecessor:
                    raise ValueError(
                        "the same node id is bound to a different predecessor"
                    )

