        """Attach the deleter's observed clock components to a tombstone."""
        existing = self._deletes.get(node_id)
        if existing is None:
            self._deletes[node_id] = dict(components)
        else:
            self._deletes[node_id] = _merge_components(existing, components)

    def retire(
