import json, copy, random
from crdt_sync import RGASession, VectorClock

def wire(s): return json.loads(json.dumps(s))
def cap(s): return wire(s.snapshot())
def restore(d): return RGASession.from_snapshot(wire(d))
def front(s): return VectorClock.from_snapshot(copy.deepcopy(s.snapshot()["clock"]))

def canon(s):
    sn = s.snapshot()
    return (json.dumps(sn["rga"], sort_keys=True),
            json.dumps(sn["clock"]["clock"], sort_keys=True),
            tuple(s.values()))

random.seed(1234)
for trial in range(60):
    ids = ["A","B","C"]
    replicas = {i: RGASession(i) for i in ids}
    packets = []
    for step in range(24):
        i = random.choice(ids)
        r = replicas[i]
        vals = r.values()
        op = random.random()
        if not vals or op < 0.55:
            r.insert(random.randrange(len(vals)+1), f"{i}{step}")
        else:
            r.delete(random.randrange(len(vals)))
        # packetize every few steps, sometimes after compaction
        if step % 3 == 0:
            p = cap(r)
            packets.append(p)
        if step % 5 == 4 and r.values() is not None:
            try:
                r.compact(front(r))
            except ValueError:
                pass
            packets.append(cap(r))
    # deliver each packet to a random subset, in random order, with duplicates
    rng = random.Random(trial)
    deck = packets * 2
    rng.shuffle(deck)
    for p in deck:
        targets = rng.sample(ids, rng.randint(1, 3))
        for i in targets:
            replicas[i].merge(restore(p))
    # everyone compacts whatever is now stable
    for r in replicas.values():
        for _ in range(3):
            if r.compact(front(r)) == 0:
                break
    # full re-exchange
    finals = [cap(r) for r in replicas.values()]
    for _ in range(3):
        for p in finals:
            for r in replicas.values():
                r.merge(restore(p))
        for r in replicas.values():
            r.compact(front(r))
    states = {canon(r) for r in replicas.values()}
    assert len(states) == 1, (trial, states)
    # id uniqueness and clock dominance in converged state
    any_r = next(iter(replicas.values()))
    allids = [tuple(n["id"]) for n in any_r.snapshot()["rga"]["nodes"]]
    assert len(allids) == len(set(allids))
    # stale replay idempotence
    before = canon(any_r)
    for p in rng.sample(packets, min(8, len(packets))):
        any_r.merge(restore(p))
    assert canon(any_r) == before
print("60 randomized trials converged; stale replay idempotent")
