    sn = s.snapshot()
    shared = {k: v for k, v in sn["rga"].items() if k != "replica_id"}
    return (json.dumps(shared, sort_keys=True),
            json.dumps(sn["clock"]["clock"], sort_keys=True),
            tuple(s.values()))

random.seed(1234)
for trial in range(80):
    ids = ["A","B","C"]
    replicas = {i: RGASession(i) for i in ids}
    packets = []
    for step in range(24):
        i = random.choice(ids); r = replicas[i]; vals = r.values()
        if not vals or random.random() < 0.55:
            r.insert(random.randrange(len(vals)+1), f"{i}{step}")
        else:
            r.delete(random.randrange(len(vals)))
        if step % 3 == 0:
            packets.append(cap(r))
        if step % 5 == 4:
            try: r.compact(front(r))
            except ValueError: pass
            packets.append(cap(r))
    rng = random.Random(trial)
    deck = packets * 2; rng.shuffle(deck)
    for p in deck:
        for i in rng.sample(ids, rng.randint(1,3)):
            replicas[i].merge(restore(p))
