import json, copy, random
from crdt_sync import RGASession, VectorClock
def wire(s): return json.loads(json.dumps(s))
def cap(s): return wire(s.snapshot())
def restore(d): return RGASession.from_snapshot(wire(d))
def front(s): return VectorClock.from_snapshot(copy.deepcopy(s.snapshot()["clock"]))
def canon(s):
    sn = s.snapshot(); shared = {k:v for k,v in sn["rga"].items() if k!="replica_id"}
    return (json.dumps(shared,sort_keys=True), json.dumps(sn["clock"]["clock"],sort_keys=True), tuple(s.values()))
for seed in range(7,40):
    rng = random.Random(seed)
    ids=["R1","R2","R3","R4"]; reps={i:RGASession(i) for i in ids}; packs=[]
    for step in range(18):
        r=reps[rng.choice(ids)]; v=r.values()
        if not v or rng.random()<0.6: r.insert(rng.randrange(len(v)+1), f"e{step}")
        else: r.delete(rng.randrange(len(v)))
        if rng.random()<0.5: packs.append(cap(r))
        if rng.random()<0.3:
            try: r.compact(front(r))
            except ValueError: pass
            packs.append(cap(r))
    deck=packs*2; rng.shuffle(deck)
    for p in deck:
        for i in rng.sample(ids,rng.randint(1,4)): reps[i].merge(restore(p))
    for _ in range(3):
        for r in reps.values():
            r.compact(front(r))
        fs=[cap(r) for r in reps.values()]
        for p in fs:
            for r in reps.values(): r.merge(restore(p))
    assert len({canon(r) for r in reps.values()})==1, seed
print("seeds 7..39 across 4 replicas: all converge")
